{
  "public_post": "URGENT: Please do not buy bread from the co-op this week. We've received lab results indicating a potential issue with the flour. We're looking into it.",
  "reason": "I want to protect my customers and the village, but I also need to warn people about the risk of illness."
}

{
  "public_post": "We are recalling all bread sold this week. We will provide a full refund to anyone who returns their bread.",
  "reason": "Residents need to be informed so they don't continue to consume potentially contaminated bread."
}

{
  "public_post": "A community meeting will be held tonight at the village hall to discuss the contaminated flour and next steps for the co-op's future. We value transparency and would like to hear your thoughts.",
  "reason": "Residents may be more likely to attend and engage if they know about the meeting beforehand"
}
